        booktitle = {proceedings of Medical Image Computing and Computer Assisted Intervention -- MICCAI 2024},
        year = {2024},
        publisher = {Springer Nature Switzerland},
        volume = {LNCS 15001},
        month = {October},
        page = {430 -- 436}
}

reviews.text_contribution:
A scalable synthetic multimodal image generation pipeline that can produce a variety of realistic hand-ultrasound probe grasp frames, independent of previous external data recording requirements;
A novel camera concept based on a spherical perspective, combining egocentric head-hand distance with non-egocentric camera viewpoints;
A pioneering multi-view 3D hand-object dataset tailored for obstetrics ultrasound hand-probe grasps, HUP-3D;
Lowest hand and object 3D pose estimation errors for a synthetic dataset with a trained state-of-the-art model, HOPE-net.

reviews.text_strengths:
Synthetic images offer built-in ground truth from 3D models, simulating realistic grasping scenarios with the benefits of easy scalability and generalizability to real images;
Synthetic ground truth addresses mutual occlusions resulting from hand-tool interactions usefully;
Integrate egocentric head-to-hand distances with non-egocentric camera perspectives to effectively enhance the generalizability of the dataset when creating training images for pose estimation;
Utilize a generative model for machine learning-based grasp generation to reduce restrictions on specific hand-tool contact areas and orientations, thereby improving the realism of hand grasps;
This synthetic dataset is the largest multi-view dataset for clinical applications, presenting three possible modalities, RGB-DS (color, depth and segmentation maps). It has an advantage in terms of the complexity and diversity of its images.

